(() => {
  const game = window.DRIFTWING;
  const { ctx, state } = game;
  const spawns = ctx.systems.spawns;
  const manager = spawns.manager;
  const world = ctx.world;
  const waterLevel = ctx.uniforms.waterLevel.value;
  const freeze = (value) => { if (value && typeof value === 'object') { Object.values(value).forEach(freeze); Object.freeze(value); } return value; };
  const kit = {
    results: [],
    waterLevel,
    check(name, ok, detail) { const line = `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`; kit.results.push(line); if (!ok) console.error(`[engine check] ${line}`); return line; },
    preset(id, engines, extra = {}) { return freeze({ id, name: id, category: extra.category ?? 'wildlife', kind: 'event', rarity: 'common', heavy: false, candidates: { cellSize: 6000, bucketSeconds: 600, chance: 0.1 }, filters: { biomes: null, timeOfDay: null, altitude: null, weather: null }, engines, lod: { near: 2500, mid: 6000, far: 14000 }, lure: null, wind: [], audio: extra.audio ?? null, journal: { title: id, description: 'An engine test configuration.' }, discovery: { radius: 800, requireInView: true }, callouts: ['{name} {distance} {direction}.', '{name} ahead, {eta}.', 'Engine check: {name}.'], lifetime: { duration: [900, 1200], despawn: { distance: 12000, hysteresis: 2000, outOfViewSeconds: 30 } }, achievements: [] }); },
    spawn(id, engines, position, extra = {}) { if (!manager.getPreset(id)) spawns.debug.addPreset(kit.preset(id, engines, extra)); const spawnId = manager.activate(id, { position, heading: extra.heading ?? state.player.heading, source: 'debug', force: true }); if (!spawnId) throw new Error(`engine check: ${id} was refused (${JSON.stringify(manager.getStats().refusals)})`); return spawnId; },
    end(id) { return manager.deactivate(id, 'engine check'); },
    alive(id) { return manager.getInstance(id) !== null; },
    part(id) { const parts = manager.getParts(id); return parts.length ? parts[0] : null; },
    memory() { const memory = ctx.renderer.info.memory; return { geometries: memory.geometries, textures: memory.textures }; },
    faunaStats() { const summary = manager.getStats().engines.fauna; return { ...summary, dustSlots: kit.fauna.stats().dustSlots }; },
    setTime(dayTime) { ctx.systems.sky.setDayTime(dayTime, { transition: 0 }); },
    slope(x, z) { return Math.max(Math.abs(world.groundHeight(x + 3, z) - world.groundHeight(x - 3, z)) / 6, Math.abs(world.groundHeight(x, z + 3) - world.groundHeight(x, z - 3)) / 6); },
    // Dry, gentle ground: a 7 x 7 grid 40 m apart all above the water and under the slope limit.
    land(minReach = 0) {
      const origin = state.player.position;
      const gentle = (x, z) => { for (let dx = -120; dx <= 120; dx += 40) for (let dz = -120; dz <= 120; dz += 40) { if (world.groundHeight(x + dx, z + dz) < waterLevel + 6) return false; if (kit.slope(x + dx, z + dz) > 0.2) return false; } return true; };
      for (let reach = minReach; reach < 60000; reach += 300) for (let step = 0; step < 36; step++) { const x = Math.round(origin.x + Math.sin(step / 36 * Math.PI * 2) * reach); const z = Math.round(origin.z - Math.cos(step / 36 * Math.PI * 2) * reach); if (gentle(x, z)) return { x, y: world.groundHeight(x, z), z }; }
      throw new Error('engine check: no dry gentle ground within 60 km');
    },
    // Open water: no ground above -0.5 m within the radius.
    water(radius = 420) {
      const origin = state.player.position;
      const open = (x, z) => { for (let dx = -radius; dx <= radius; dx += 70) for (let dz = -radius; dz <= radius; dz += 70) if (world.heightAt(x + dx, z + dz) > waterLevel - 0.5) return false; return true; };
      for (let reach = 0; reach < 60000; reach += 400) for (let step = 0; step < 48; step++) { const x = origin.x + Math.cos(step / 48 * Math.PI * 2) * reach; const z = origin.z + Math.sin(step / 48 * Math.PI * 2) * reach; if (open(x, z)) return { x, z }; }
      throw new Error('engine check: no open water found within 60 km');
    },
    // A shoreline point in about 0.3 m of water: march out until the ground crosses the water line, then bisect.
    shore() {
      const origin = state.player.position;
      for (let step = 0; step < 24; step++) {
        const dirX = Math.sin(step / 24 * Math.PI * 2);
        const dirZ = -Math.cos(step / 24 * Math.PI * 2);
        let previous = world.groundHeight(origin.x, origin.z) - waterLevel;
        for (let reach = 100; reach < 40000; reach += 100) {
          const height = world.groundHeight(origin.x + dirX * reach, origin.z + dirZ * reach) - waterLevel;
          if (previous > 0 && height <= 0) {
            let dry = reach - 100;
            let wet = reach;
            for (let iteration = 0; iteration < 24; iteration++) { const mid = (dry + wet) / 2; if (world.groundHeight(origin.x + dirX * mid, origin.z + dirZ * mid) - waterLevel > -0.3) dry = mid; else wet = mid; }
            return { x: Math.round(origin.x + dirX * wet), z: Math.round(origin.z + dirZ * wet), dirX, dirZ, depth: waterLevel - world.groundHeight(Math.round(origin.x + dirX * wet), Math.round(origin.z + dirZ * wet)) };
          }
          previous = height;
        }
      }
      throw new Error('engine check: no shoreline found within 40 km');
    },
    // Puts the craft `distance` m from a point, `up` m above the ground (or the water), facing it
    // (turned `yaw` degrees to the left, so the point shows beside the craft in the chase view).
    approach(target, distance, up, side = 0, yaw = 0) {
      const dx = target.x - state.player.position.x;
      const dz = target.z - state.player.position.z;
      const length = Math.hypot(dx, dz) || 1;
      const ux = dx / length;
      const uz = dz / length;
      const x = target.x - ux * distance - uz * side;
      const z = target.z - uz * distance + ux * side;
      const floor = Math.max(world.groundHeight(x, z), waterLevel);
      const heading = Math.atan2(target.x - x, -(target.z - z)) * 180 / Math.PI - yaw;
      ctx.systems.flight.resetTo({ x, y: floor + up, z, heading });
      return { x, y: floor + up, z, heading };
    },
    events: { stampede: [], flush: [], race: [] },
  };
  ctx.bus.on('fauna:stampede', (event) => kit.events.stampede.push(event.trigger));
  ctx.bus.on('fauna:flush', (event) => kit.events.flush.push(event.count));
  ctx.bus.on('fauna:race', (event) => kit.events.race.push(event.racing));
  kit.fauna = manager.registry.get('fauna');
  window.__faunaModes = kit;
  return `backend ${game.backend}; water level ${waterLevel}; fauna engine ${kit.fauna ? 'registered' : 'missing'}`;
})()

